def load_ciphertext():
    for name in ("flag.enc", "flag(1).enc"):
        p = Path(name)
        if p.exists():
            return json.loads(p.read_text())
    raise SystemExit("flag.enc not found")


def xor_all(chunks):
    return bytes(x ^ y ^ z ^ u ^ v for x, y, z, u, v in zip(*chunks))


def main():
    z = load_ciphertext()
    n = z["N"]
    shares = []

    for idx, row in enumerate(RECOVERED_ROWS):
        b = row[:n]
        a = row[n:]
        plaintext = None

        # Sign does not change h. Try both and let HMAC validate the correct key.
        for sign in (1, -1):
            aa = [sign * x for x in a]
            bb = [sign * x for x in b]
            try:
                plaintext = fence.dc(aa, bb, z["H"][idx], z["C"][idx])
                break
            except ValueError:
                pass

        if plaintext is None:
            raise SystemExit(f"failed to decrypt share {idx}")
        shares.append(plaintext)

    flag = xor_all(shares)
    print(f"<FLAG>{flag.decode()}</FLAG>")


if __name__ == "__main__":
    main()
